head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL05033";
scwin.form = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil05033.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_bzCd", fn: function(){ return ((dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '0' || (dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '2'); } }, { id: "if_bzCd_2", fn: function(){ return ((dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '1' || (dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '3'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_acntclsYymm", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "acntclsYymm")); } },
        { childId: "ipt_acntclsYymm_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "acntclsYymm")); } },
        { childId: "ipt_acntclsYymm_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "acntclsYymm")); } },
        { childId: "ipt_totAsstAmt", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "totAsstAmt")); } },
        { childId: "ipt_totAsstAmt_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "totAsstAmt")); } },
        { childId: "ipt_totAsstAmt_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "totAsstAmt")); } },
        { childId: "ipt_totDebtAmt", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "totDebtAmt")); } },
        { childId: "ipt_totDebtAmt_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "totDebtAmt")); } },
        { childId: "ipt_totDebtAmt_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "totDebtAmt")); } },
        { childId: "ipt_totCap", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "totCap")); } },
        { childId: "ipt_totCap_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "totCap")); } },
        { childId: "ipt_totCap_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "totCap")); } },
        { childId: "ipt_cap", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "cap")); } },
        { childId: "ipt_cap_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "cap")); } },
        { childId: "ipt_cap_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "cap")); } },
        { childId: "ipt_bzProftAmt", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "bzProftAmt")); } },
        { childId: "ipt_bzProftAmt_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "bzProftAmt")); } },
        { childId: "ipt_bzProftAmt_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "bzProftAmt")); } },
        { childId: "ipt_ordnincmAmt", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "ordnincmAmt")); } },
        { childId: "ipt_ordnincmAmt_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "ordnincmAmt")); } },
        { childId: "ipt_ordnincmAmt_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "ordnincmAmt")); } },
        { childId: "ipt_netincmAmt", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "netincmAmt")); } },
        { childId: "ipt_netincmAmt_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "netincmAmt")); } },
        { childId: "ipt_netincmAmt_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "netincmAmt")); } },
        { childId: "ipt_bzActivCashFlowAmt", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "bzActivCashFlowAmt")); } },
        { childId: "ipt_bzActivCashFlowAmt_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "bzActivCashFlowAmt")); } },
        { childId: "ipt_bzActivCashFlowAmt_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "bzActivCashFlowAmt")); } },
        { childId: "ipt_acntclsYymmTmp", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "acntclsYymm")); } },
        { childId: "ipt_acntclsYymmTmp_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "acntclsYymm")); } },
        { childId: "ipt_acntclsYymmTmp_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "acntclsYymm")); } },
        { childId: "ipt_fbzNetcap", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "fbzNetcap")); } },
        { childId: "ipt_fbzNetcap_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "fbzNetcap")); } },
        { childId: "ipt_fbzNetcap_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "fbzNetcap")); } },
        { childId: "ipt_totRiskAmt", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "totRiskAmt")); } },
        { childId: "ipt_totRiskAmt_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "totRiskAmt")); } },
        { childId: "ipt_totRiskAmt_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "totRiskAmt")); } },
        { childId: "ipt_reqPersisPrincCapVal", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "reqPersisPrincCapVal")); } },
        { childId: "ipt_reqPersisPrincCapVal_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "reqPersisPrincCapVal")); } },
        { childId: "ipt_reqPersisPrincCapVal_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "reqPersisPrincCapVal")); } },
        { childId: "ipt_eqtycap", fn: function () { return String(dlt_readDataVOArrayDrv.getCellData(0, "eqtycap")); } },
        { childId: "ipt_eqtycap_2", fn: function () { return String(dlt_readDataVOArrayDrv.getCellData(1, "eqtycap")); } },
        { childId: "ipt_otcDrvfncTrdTotRiskAmt", fn: function () { return String(dlt_readDataVOArrayDrv.getCellData(0, "otcDrvfncTrdTotRiskAmt")); } },
        { childId: "ipt_otcDrvfncTrdTotRiskAmt_2", fn: function () { return String(dlt_readDataVOArrayDrv.getCellData(1, "otcDrvfncTrdTotRiskAmt")); } },
        { childId: "ipt_fbzNetcap_4", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "fbzNetcap")); } },
        { childId: "ipt_eqtycap_3", fn: function () { return String(dlt_readDataVOArrayDrv.getCellData(0, "eqtycap")); } },
        { childId: "ipt_totRiskAmt_4", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "totRiskAmt")); } },
        { childId: "ipt_otcDrvfncTrdTotRiskAmt_3", fn: function () { return String(dlt_readDataVOArrayDrv.getCellData(0, "otcDrvfncTrdTotRiskAmt")); } },
        { childId: "ipt_reqPersisPrincCapVal_4", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "reqPersisPrincCapVal")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.form = (document.ElwForm || { elements: [] });
        $c.util.getComponent('slc_audtOpinTpCd').setItemDisabled(0, !!(true));
        $c.util.getComponent('slc_audtOpinTpCd').setItemDisabled(1, !!(true));
        $c.util.getComponent('slc_audtOpinTpCd').setItemDisabled(2, !!(true));
        scwin.calNetRto(1);
        scwin.calNetRto(2);
        scwin.calNetRto(3);
        scwin.commaValueAll();
        scwin.commaValueAllN();
        scwin.calNetRto();
        scwin.calNetRto(1);
        scwin.calOtcRto();
        scwin.commaValueAll();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05033.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldfil05033: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_ElwPageUsrSearch_onclick
 * @description 「목록보기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ElwPageUsrSearch_onclick = async function(e){
    try {
        await scwin.elwPageUsrSearch()
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil05033.btn_ElwPageUsrSearch_onclick" });
    }
};

/**
 * @method
 * @name __ev_2_btn_ElwPageUsrSearch_onclick
 * @description __ev_2_btn_ElwPageUsrSearch 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__ev_2_btn_ElwPageUsrSearch_onclick = async function(e){
    try {
        await scwin.elwPageUsrSearch()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05033.__ev_2_btn_ElwPageUsrSearch_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name calOtcRto
 * @description cal Otc Rto 처리
 * @returns {void}
 * @hidden N
 */
scwin.calOtcRto = function () {
    if (($c.util.getComponent('ipt_otcDrvfncTrdTotRiskAmt').getValue() == null ? '' : String($c.util.getComponent('ipt_otcDrvfncTrdTotRiskAmt').getValue())) !== '' && ($c.util.getComponent('ipt_eqtycap').getValue() == null ? '' : String($c.util.getComponent('ipt_eqtycap').getValue())) !== '') {
        $c.util.getComponent('ipt_otcRto').setValue(Math.round((scwin.rmComma($c.util.getComponent('ipt_otcDrvfncTrdTotRiskAmt').getValue()) / scwin.rmComma($c.util.getComponent('ipt_eqtycap').getValue())) * 10000) / 100);
    }
};

/**
 * @method
 * @name calNetRto
 * @description cal Net Rto 처리
 * @param {*} num num
 * @returns {void}
 * @hidden N
 */
scwin.calNetRto = function (num) {
    if (num === 1) {
        if (($c.util.getComponent('ipt_fbzNetcap').getValue() == null ? '' : String($c.util.getComponent('ipt_fbzNetcap').getValue())) !== '' && ($c.util.getComponent('ipt_totRiskAmt').getValue() == null ? '' : String($c.util.getComponent('ipt_totRiskAmt').getValue())) !== '' && ($c.util.getComponent('ipt_reqPersisPrincCapVal').getValue() == null ? '' : String($c.util.getComponent('ipt_reqPersisPrincCapVal').getValue())) !== '') {
            $c.util.getComponent('ipt_netRto').setValue(Math.round(((scwin.rmComma($c.util.getComponent('ipt_fbzNetcap').getValue()) - scwin.rmComma($c.util.getComponent('ipt_totRiskAmt').getValue())) / scwin.rmComma($c.util.getComponent('ipt_reqPersisPrincCapVal').getValue())) * 10000) / 100);
        }
    }
};

/**
 * @method
 * @name rmComma
 * @description rm Comma 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.rmComma = function (str) {

    //    if( str == null || str == "" || str == 0 ) return '';
    //    if( str == null || str == ""  ) return '';
    if( str == null || str === ""  ) return Number(str);   // 2009.07.02 수정. 항목 미입력시 합계 오류발생

    reg =  new RegExp(",","g");

    return Number(str.replace(reg,''));
};

/**
 * @method
 * @name commaValueAll
 * @description comma Value All 처리
 * @returns {void}
 * @hidden N
 */
scwin.commaValueAll = function () {

    for(let i=0 ; i < 3 ; i++ ) {
        $c.fil.setComma($c.util.getComponent(["ipt_totAsstAmt", "ipt_totAsstAmt_2", "ipt_totAsstAmt_3"][i])); // 총자산금액
        $c.fil.setComma($c.util.getComponent(["ipt_cap", "ipt_cap_2", "ipt_cap_3"][i])); // 자본금
        $c.fil.setComma($c.util.getComponent(["ipt_totDebtAmt", "ipt_totDebtAmt_2", "ipt_totDebtAmt_3"][i])); // 총부채금액
        $c.fil.setComma($c.util.getComponent(["ipt_totCap", "ipt_totCap_2", "ipt_totCap_3"][i])); // 총자본금
        $c.fil.setComma($c.util.getComponent(["ipt_bzProftAmt", "ipt_bzProftAmt_2", "ipt_bzProftAmt_3"][i])); // 영업이익금액
        $c.fil.setComma($c.util.getComponent(["ipt_ordnincmAmt", "ipt_ordnincmAmt_2", "ipt_ordnincmAmt_3"][i])); // 경상이익금액
        $c.fil.setComma($c.util.getComponent(["ipt_netincmAmt", "ipt_netincmAmt_2", "ipt_netincmAmt_3"][i])); // 당기순이익금액
        $c.fil.setComma($c.util.getComponent(["ipt_bzActivCashFlowAmt", "ipt_bzActivCashFlowAmt_2", "ipt_bzActivCashFlowAmt_3"][i])); // 영업활동현금흐름금액
        $c.fil.setComma($c.util.getComponent(["ipt_fbzNetcap", "ipt_fbzNetcap_2", "ipt_fbzNetcap_3", "ipt_fbzNetcap_4"][i])); // 영업용순자본금
        $c.fil.setComma($c.util.getComponent(["ipt_totRiskAmt", "ipt_totRiskAmt_2", "ipt_totRiskAmt_3", "ipt_totRiskAmt_4"][i])); // 총위험금액
        $c.fil.setComma($c.util.getComponent(["ipt_reqPersisPrincCapVal", "ipt_reqPersisPrincCapVal_2", "ipt_reqPersisPrincCapVal_3", "ipt_reqPersisPrincCapVal_4"][i])); // 필요유지자기자본
        $c.fil.setComma($c.util.getComponent(["ipt_netRto", "ipt_netRto_2", "ipt_netRto_3", "ipt_netRto_4", "ipt_netRto_5"][i])); // 순자본비율

        $c.fil.setComma($c.util.getComponent(["ipt_eqtycap", "ipt_eqtycap_2", "ipt_eqtycap_3"][i])); // 자기자본금
        $c.fil.setComma($c.util.getComponent(["ipt_otcDrvfncTrdTotRiskAmt", "ipt_otcDrvfncTrdTotRiskAmt_2", "ipt_otcDrvfncTrdTotRiskAmt_3"][i])); // 장외파생금융상품거래총위험금액
    }
};

/**
 * @method
 * @name commaValueAllN
 * @description comma Value All N 처리
 * @returns {void}
 * @hidden N
 */
scwin.commaValueAllN = function () {

    for(let i=0 ; i < 3 ; i++ ) {
        $c.fil.setComma($c.util.getComponent(["ipt_totAsstAmt", "ipt_totAsstAmt_2", "ipt_totAsstAmt_3"][i])); // 총자산금액
        $c.fil.setComma($c.util.getComponent(["ipt_cap", "ipt_cap_2", "ipt_cap_3"][i])); // 자본금
        $c.fil.setComma($c.util.getComponent(["ipt_totDebtAmt", "ipt_totDebtAmt_2", "ipt_totDebtAmt_3"][i])); // 총부채금액
        $c.fil.setComma($c.util.getComponent(["ipt_totCap", "ipt_totCap_2", "ipt_totCap_3"][i])); // 총자본금
        $c.fil.setComma($c.util.getComponent(["ipt_bzProftAmt", "ipt_bzProftAmt_2", "ipt_bzProftAmt_3"][i])); // 영업이익금액
        $c.fil.setComma($c.util.getComponent(["ipt_ordnincmAmt", "ipt_ordnincmAmt_2", "ipt_ordnincmAmt_3"][i])); // 경상이익금액
        $c.fil.setComma($c.util.getComponent(["ipt_netincmAmt", "ipt_netincmAmt_2", "ipt_netincmAmt_3"][i])); // 당기순이익금액
        $c.fil.setComma($c.util.getComponent(["ipt_bzActivCashFlowAmt", "ipt_bzActivCashFlowAmt_2", "ipt_bzActivCashFlowAmt_3"][i])); // 영업활동현금흐름금액
        $c.fil.setComma($c.util.getComponent(["ipt_fbzNetcap", "ipt_fbzNetcap_2", "ipt_fbzNetcap_3", "ipt_fbzNetcap_4"][i])); // 영업용순자본금
        $c.fil.setComma($c.util.getComponent(["ipt_totRiskAmt", "ipt_totRiskAmt_2", "ipt_totRiskAmt_3", "ipt_totRiskAmt_4"][i])); // 총위험금액

        $c.fil.setComma($c.util.getComponent(["ipt_eqtycap", "ipt_eqtycap_2", "ipt_eqtycap_3"][i])); // 자기자본금
        $c.fil.setComma($c.util.getComponent(["ipt_otcDrvfncTrdTotRiskAmt", "ipt_otcDrvfncTrdTotRiskAmt_2", "ipt_otcDrvfncTrdTotRiskAmt_3"][i])); // 장외파생금융상품거래총위험금액
    }
};

/**
 * @method
 * @name elwPageUsrSearch
 * @description elw Page Usr Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.elwPageUsrSearch = async function () {
    scwin.form.bzCd.value   = BZ_USRLST ;

    if( scwin.form.isuNm != null ) {
        scwin.form.isuNm.value  = "" ;
    }

    scwin.form.action       = '/list/elwPage.do';
    scwin.form.method.value = 'elwPageSearch';
    await moveUrl('/list/elwPage.do', {});

};
